import { describe, it, expect } from 'vitest'
import chapterDetachments from './chapterDetachments.js'
import { loadFaction } from './factions/index.js'
import { loadRosterFaction } from './roster/index.js'

// The faction page offers a Chapter the Codex detachments from this file (useFactionPage.js); the
// roster editor offers them from the roster data. Both are generated by gen-roster-data.mjs, but
// the page finds each one by NAME in another faction's file and silently skips a name it cannot
// find — which is how a Deathwatch player came to see two detachments instead of seventeen.
describe('chapterDetachments', () => {
  const slugs = Object.keys(chapterDetachments)

  it('covers the five Chapters and the Space Marines', () => {
    expect(slugs.sort()).toEqual(['black-templars', 'blood-angels', 'dark-angels', 'deathwatch', 'space-marines', 'space-wolves'])
  })

  it.each(slugs)('%s: every entry is a detachment of the file it is read from', async (slug) => {
    const missing = []
    for (const e of chapterDetachments[slug]) {
      const src = await loadFaction(e.from)
      if (!src?.en.detachments.some((d) => d.name === e.name)) missing.push(`${e.name} (${e.from})`)
    }
    expect(missing).toEqual([])
  })

  it.each(slugs)('%s: the page offers what the roster editor offers, at the same cost', async (slug) => {
    const own = (await loadFaction(slug)).en.detachments.map((d) => d.name)
    const roster = await loadRosterFaction(slug)
    const editor = roster.detachments.map((d) => `${d.name} ${d.dp}`).sort()
    const page = []
    for (const name of own) page.push(`${name} ${roster.detachments.find((d) => d.name === name)?.dp}`)
    for (const e of chapterDetachments[slug]) {
      const src = await loadFaction(e.from)
      page.push(`${e.name} ${e.dp ?? src.en.detachments.find((d) => d.name === e.name).dp}`)
    }
    expect(page.sort()).toEqual(editor)
  })
})
